engine.auvListUsageFiles:
function auvListUsageFiles() {
  var owner = "apndrewn";
  var repo  = "eli-data";
  var url = "https://api.github.com/repos/" + owner + "/" + repo +
    "/contents/usage?t=" + Date.now();
  return fetch(url, {
    cache: "no-store",
    headers: { "Accept": "application/vnd.github+json" },
  }).then(function (r) {
    if (r.status === 404) return [];
    if (!r.ok) throw new Error("list failed: HTTP " + r.status);
    return r.json();
  }).then(function (arr) {
    if (!Array.isArray(arr)) return [];
    return arr.filter(function (e) {
      return e && e.type === "file" && /\.json$/i.test(String(e.name || ""));
    }).map(function (e) {
      return { name: e.name, download_url: e.download_url };
    });
  });
}

// Fetch + parse a single usage JSON. Returns the digest object or null on
// failure. Caller is expected to feed download_url straight in.

engine.auvFetchDigest:
function auvFetchDigest(downloadUrl) {
  if (!downloadUrl) return Promise.resolve(null);
  // Cache-bust to defeat browser cache; GitHub raw URLs include a SHA-ish
  // refspec but the URL is unique-per-commit so this is belt-and-suspenders.
  var url = downloadUrl + (downloadUrl.indexOf("?") === -1 ? "?" : "&") + "_t=" + Date.now();
  return fetch(url, { cache: "no-store" }).then(function (r) {
    if (!r.ok) return null;
    return r.json();
  }).then(function (j) {
    if (!j || !Array.isArray(j.days)) return null;
    return j;
  }).catch(function () { return null; });
}

// Aggregate a list of digests into the shape the dashboard renders.
// Returns:
//   {
//     users: [{ userKey, userName, sessions, activeDays, lastPushAt, days }],
//     tools: [{ tool, launches }],            // sorted desc
//     daily: [{ date, sessions }],            // sorted asc, last 7 days only
//     grid:  { dates:[YYYY-MM-DD,...], users:[{userKey,userName,cells:{date:{sessions,topTool}}}] },
//   }

engine.auvAggregate:
function auvAggregate(digests) {
  digests = Array.isArray(digests) ? digests.filter(Boolean) : [];
  var users = [];
  var toolTotals = {};
  var dailyTotals = {}; // date -> sessions
  var dateSet = {};
  digests.forEach(function (d) {
    var key = d.userKey || "unknown";
    var name = d.userName || key;
    var days = Array.isArray(d.days) ? d.days : [];
    var sessions = 0;
    var activeDays = 0;
    var lastPushAt = 0;
    days.forEach(function (day) {
      if (!day || !day.date) return;
      dateSet[day.date] = true;
      var s = Number(day.sessions || 0);
      sessions += s;
      if (s > 0 || Object.keys(day.toolsUsed || {}).length) activeDays += 1;
      dailyTotals[day.date] = (dailyTotals[day.date] || 0) + s;
      if (Number(day.lastActiveAt || 0) > lastPushAt) lastPushAt = Number(day.lastActiveAt);
      var tu = day.toolsUsed || {};
      Object.keys(tu).forEach(function (t) {
        toolTotals[t] = (toolTotals[t] || 0) + (Number(tu[t]) || 0);
      });
    });
    // generatedAt is the most reliable "last push" signal — fall back to
    // the last lastActiveAt from days if generatedAt missing.
    var gen = d.generatedAt ? Date.parse(d.generatedAt) : 0;
    if (gen && gen > lastPushAt) lastPushAt = gen;
    users.push({
      userKey: key,
      userName: name,
      sessions: sessions,
      activeDays: activeDays,
      lastPushAt: lastPushAt,
      days: days,
    });
  });
  // Most-active users — sort by sessions desc, then by activeDays desc.
  users.sort(function (a, b) {
    if (b.sessions !== a.sessions) return b.sessions - a.sessions;
    return b.activeDays - a.activeDays;
  });
  // Most-used tools — flatten + sort.
  var tools = Object.keys(toolTotals).map(function (t) {
    return { tool: t, launches: toolTotals[t] };
  }).sort(function (a, b) { return b.launches - a.launches; });
  // Daily series — last 7 days (descending then sliced then re-sorted asc).
  var sortedDates = Object.keys(dailyTotals).sort();
  var last7 = sortedDates.slice(-7);
  var daily = last7.map(function (date) {
    return { date: date, sessions: dailyTotals[date] || 0 };
  });
  // Grid — same date columns as daily, per user.
  var grid = {
    dates: last7.slice(),
    users: users.map(function (u) {
      var cells = {};
      (u.days || []).forEach(function (day) {
        if (!day || !day.date) return;
        if (last7.indexOf(day.date) === -1) return;
        var topTool = "";
        var topCount = 0;
        var tu = day.toolsUsed || {};
        Object.keys(tu).forEach(function (t) {
          var c = Number(tu[t]) || 0;
          if (c > topCount) { topCount = c; topTool = t; }
        });
        cells[day.date] = {
          sessions: Number(day.sessions || 0),
          topTool: topTool,
          topCount: topCount,
        };
      });
      return { userKey: u.userKey, userName: u.userName, cells: cells };
    }),
  };
  return { users: users, tools: tools, daily: daily, grid: grid };
}

// Build a CSV string from the raw digest list. Columns: user,date,tool,launches.
// One row per (user, date, tool). Sessions emitted as a synthetic
// tool=__session row so the CSV is self-contained.

engine.auvBuildCsv:
function auvBuildCsv(digests) {
  var rows = [["user", "date", "tool", "launches"]];
  function _esc(v) {
    var s = String(v == null ? "" : v);
    if (/[",\r\n]/.test(s)) return '"' + s.replace(/"/g, '""') + '"';
    return s;
  }
  (Array.isArray(digests) ? digests : []).forEach(function (d) {
    var name = d.userName || d.userKey || "unknown";
    var days = Array.isArray(d.days) ? d.days : [];
    days.forEach(function (day) {
      if (!day || !day.date) return;
      var tu = day.toolsUsed || {};
      Object.keys(tu).forEach(function (t) {
        rows.push([name, day.date, t, Number(tu[t]) || 0]);
      });
      if (Number(day.sessions || 0) > 0) {
        rows.push([name, day.date, "__session", Number(day.sessions) || 0]);
      }
    });
  });
  return rows.map(function (r) { return r.map(_esc).join(","); }).join("\r\n");
}

view.renderDashboard:
function renderDashboard(opts) {
  var host = opts && opts.host;
  var data = (opts && opts.data) || { users: [], tools: [], daily: [], grid: { dates: [], users: [] } };
  var onRefresh = opts && opts.onRefresh;
  var onExport  = opts && opts.onExport;
  var totalDigests = (opts && opts.totalDigests) || 0;
  var cachedAt = (opts && opts.cachedAt) || 0;
  if (!host) return;

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _fmtTool(t) {
    // ask_eli -> Ask Eli, admin_library_publisher -> Admin Library Publisher
    return String(t || "").split("_").map(function (p) {
      return p ? p.charAt(0).toUpperCase() + p.slice(1) : "";
    }).join(" ");
  }
  function _fmtDateShort(iso) {
    if (!iso) return "—";
    // "2026-05-13" → "May 13"
    var parts = String(iso).split("-");
    if (parts.length !== 3) return iso;
    var monthNames = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
    var m = Number(parts[1]) - 1;
    var d = Number(parts[2]);
    if (m < 0 || m > 11 || !d) return iso;
    return monthNames[m] + " " + d;
  }
  function _fmtAgo(ms) {
    if (!ms) return "never";
    var sec = Math.max(0, Math.floor((Date.now() - ms) / 1000));
    if (sec < 60) return sec + "s ago";
    if (sec < 3600) return Math.floor(sec / 60) + "m ago";
    if (sec < 86400) return Math.floor(sec / 3600) + "h ago";
    return Math.floor(sec / 86400) + "d ago";
  }
  function _isStale(lastPushAt) {
    if (!lastPushAt) return true;
    return (Date.now() - lastPushAt) > (3 * 24 * 60 * 60 * 1000);
  }

  // Bar-width as % of maximum in a list. Returns 0..100 (capped).
  function _barPct(value, max) {
    if (!max || max <= 0) return 0;
    var pct = (Number(value) / Number(max)) * 100;
    if (pct < 1 && value > 0) pct = 1; // ensure visible
    if (pct > 100) pct = 100;
    return pct;
  }

  var maxUserSessions = (data.users[0] && data.users[0].sessions) || 0;
  var maxToolLaunches = (data.tools[0] && data.tools[0].launches) || 0;
  var maxDaily = data.daily.reduce(function (a, d) {
    return Math.max(a, d.sessions || 0);
  }, 0);

  // ─── Build HTML ────────────────────────────────────────────────────
  var html = '';
  html += '<div class="_auv_root">';

  // Header bar
  html += '<div class="_auv_header">';
  html +=   '<div>';
  html +=     '<div class="_auv_header_eyebrow">ADMIN — RESTRICTED</div>';
  html +=     '<div class="_auv_header_title">📊 Usage Dashboard</div>';
  html +=     '<div class="_auv_header_sub">' + totalDigests + ' user' + (totalDigests === 1 ? '' : 's') +
              ' · cache ' + _fmtAgo(cachedAt) + '</div>';
  html +=   '</div>';
  html +=   '<div class="_auv_header_btns">';
  html +=     '<button class="_auv_btn _auv_btn_platinum" id="auvRefresh">↻ Refresh</button>';
  html +=     '<button class="_auv_btn _auv_btn_platinum" id="auvExport">⬇ Export CSV</button>';
  html +=   '</div>';
  html += '</div>';

  if (!totalDigests) {
    html += '<div class="_auv_empty">' +
      'No usage files found in <code>apndrewn/eli-data/usage/</code>. ' +
      'Either no users have pushed yet, or the eli_telemetry tool is not installed for them.' +
      '</div>';
    html += '</div>'; // _auv_root
    host.innerHTML = html;
    var refreshEl0 = host.querySelector("#auvRefresh");
    if (refreshEl0 && onRefresh) refreshEl0.onclick = onRefresh;
    return;
  }

  // Panel 1: Most active users
  html += '<div class="_auv_card">';
  html +=   '<div class="_auv_card_head"><span class="_auv_card_title">🥇 Most Active Users</span></div>';
  html +=   '<div class="_auv_card_body">';
  if (!data.users.length) {
    html += '<div class="_auv_empty_inner">No active users yet.</div>';
  } else {
    html += '<div class="_auv_list">';
    data.users.forEach(function (u) {
      var pct = _barPct(u.sessions, maxUserSessions);
      var stale = _isStale(u.lastPushAt);
      html += '<div class="_auv_row' + (stale ? ' _auv_row_stale' : '') + '">';
      html +=   '<div class="_auv_row_top">';
      html +=     '<span class="_auv_row_label">' + _esc(u.userName) + '</span>';
      html +=     '<span class="_auv_row_meta">' +
                    u.sessions + ' session' + (u.sessions === 1 ? '' : 's') +
                    ' · ' + u.activeDays + ' day' + (u.activeDays === 1 ? '' : 's') +
                    ' · pushed ' + _fmtAgo(u.lastPushAt) +
                  '</span>';
      html +=   '</div>';
      html +=   '<div class="_auv_bar"><div class="_auv_bar_fill" style="width:' + pct.toFixed(1) + '%"></div></div>';
      html += '</div>';
    });
    html += '</div>';
  }
  html +=   '</div>';
  html += '</div>';

  // Panel 2: Most-used tools
  html += '<div class="_auv_card">';
  html +=   '<div class="_auv_card_head"><span class="_auv_card_title">🔧 Most-Used Tools</span></div>';
  html +=   '<div class="_auv_card_body">';
  if (!data.tools.length) {
    html += '<div class="_auv_empty_inner">No tool launches recorded yet.</div>';
  } else {
    html += '<div class="_auv_list">';
    data.tools.forEach(function (t) {
      var pct = _barPct(t.launches, maxToolLaunches);
      html += '<div class="_auv_row">';
      html +=   '<div class="_auv_row_top">';
      html +=     '<span class="_auv_row_label">' + _esc(_fmtTool(t.tool)) + '</span>';
      html +=     '<span class="_auv_row_meta">' + t.launches + '</span>';
      html +=   '</div>';
      html +=   '<div class="_auv_bar"><div class="_auv_bar_fill" style="width:' + pct.toFixed(1) + '%"></div></div>';
      html += '</div>';
    });
    html += '</div>';
  }
  html +=   '</div>';
  html += '</div>';

  // Panel 3: Daily activity (last 7 days)
  html += '<div class="_auv_card">';
  html +=   '<div class="_auv_card_head"><span class="_auv_card_title">📅 Daily Activity — Last 7 Days</span></div>';
  html +=   '<div class="_auv_card_body">';
  if (!data.daily.length) {
    html += '<div class="_auv_empty_inner">No daily data.</div>';
  } else {
    html += '<div class="_auv_daily">';
    data.daily.forEach(function (d) {
      var pct = _barPct(d.sessions, maxDaily);
      html += '<div class="_auv_daily_col">';
      html +=   '<div class="_auv_daily_bar_wrap"><div class="_auv_daily_bar" style="height:' + Math.max(2, pct).toFixed(1) + '%"></div></div>';
      html +=   '<div class="_auv_daily_count">' + d.sessions + '</div>';
      html +=   '<div class="_auv_daily_date">' + _esc(_fmtDateShort(d.date)) + '</div>';
      html += '</div>';
    });
    html += '</div>';
  }
  html +=   '</div>';
  html += '</div>';

  // Panel 4: Per-user × per-day grid (collapsible)
  html += '<div class="_auv_card">';
  html +=   '<div class="_auv_card_head _auv_grid_head" id="auvGridHead">';
  html +=     '<span class="_auv_card_title">📐 Per-User × Per-Day Grid</span>';
  html +=     '<span class="_auv_grid_toggle" id="auvGridToggle">▸ Expand</span>';
  html +=   '</div>';
  html +=   '<div class="_auv_card_body _auv_grid_body" id="auvGridBody" style="display:none">';
  if (!data.grid.users.length || !data.grid.dates.length) {
    html += '<div class="_auv_empty_inner">Not enough data for grid view.</div>';
  } else {
    html += '<div class="_auv_grid_scroll"><table class="_auv_grid_tbl">';
    html += '<thead><tr><th class="_auv_grid_user_col">User</th>';
    data.grid.dates.forEach(function (date) {
      html += '<th>' + _esc(_fmtDateShort(date)) + '</th>';
    });
    html += '</tr></thead><tbody>';
    data.grid.users.forEach(function (u) {
      html += '<tr><td class="_auv_grid_user_col">' + _esc(u.userName) + '</td>';
      data.grid.dates.forEach(function (date) {
        var cell = u.cells[date];
        if (!cell || !cell.sessions) {
          html += '<td class="_auv_grid_cell _auv_grid_cell_empty">·</td>';
        } else {
          var top = cell.topTool ? _fmtTool(cell.topTool) : "—";
          html += '<td class="_auv_grid_cell" title="' + _esc(top) + ' · ' + cell.topCount + ' launch' + (cell.topCount === 1 ? '' : 'es') + '">';
          html +=   '<div class="_auv_grid_sessions">' + cell.sessions + '</div>';
          html +=   '<div class="_auv_grid_toptool">' + _esc(top) + '</div>';
          html += '</td>';
        }
      });
      html += '</tr>';
    });
    html += '</tbody></table></div>';
  }
  html +=   '</div>';
  html += '</div>';

  html += '<div class="_auv_footer">' +
    'Sessions count one boot per user per day. Stale rows (dimmed) haven\'t pushed in 3+ days. ' +
    'Source: <code>github.com/apndrewn/eli-data/usage/</code>. Cache: 5 minutes.' +
    '</div>';
  html += '</div>'; // _auv_root

  host.innerHTML = html;

  // Wire handlers (idempotent — caller re-renders on refresh).
  var refreshEl = host.querySelector("#auvRefresh");
  if (refreshEl && onRefresh) refreshEl.onclick = onRefresh;
  var exportEl = host.querySelector("#auvExport");
  if (exportEl && onExport) exportEl.onclick = onExport;
  var gridHead = host.querySelector("#auvGridHead");
  var gridBody = host.querySelector("#auvGridBody");
  var gridToggle = host.querySelector("#auvGridToggle");
  if (gridHead && gridBody && gridToggle) {
    gridHead.style.cursor = "pointer";
    gridHead.onclick = function () {
      var open = gridBody.style.display !== "none";
      gridBody.style.display = open ? "none" : "";
      gridToggle.textContent = open ? "▸ Expand" : "▾ Collapse";
    };
  }
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.tools) return;
  var bundle = eli.tools._loaded && eli.tools._loaded.admin_usage_viewer;
  if (!bundle) return;
  var efns = bundle._eliEngineFns || {};
  var vfns = bundle._eliViewFns || {};
  var auvListUsageFiles = efns.auvListUsageFiles;
  var auvFetchDigest    = efns.auvFetchDigest;
  var auvAggregate      = efns.auvAggregate;
  var auvBuildCsv       = efns.auvBuildCsv;
  var renderDashboard   = vfns.renderDashboard;
  if (!auvListUsageFiles || !auvAggregate || !renderDashboard) {
    eli.log.event("tool", "admin_usage_viewer_load_failed", {
      hasList: !!auvListUsageFiles, hasAgg: !!auvAggregate, hasView: !!renderDashboard,
    });
    return;
  }

  var CACHE_KEY = "_admin_usage_cache";
  var CACHE_AT_KEY = "_admin_usage_cache_at";
  var CACHE_TTL_MS = 5 * 60 * 1000;

  function _readCache() {
    try {
      var s = eli.compat.lsGet(CACHE_KEY);
      var at = Number(eli.compat.lsGet(CACHE_AT_KEY) || 0);
      if (!s || !at) return null;
      if ((Date.now() - at) > CACHE_TTL_MS) return null;
      return { digests: JSON.parse(s), cachedAt: at };
    } catch (e) { return null; }
  }
  function _writeCache(digests) {
    try {
      eli.compat.lsSet(CACHE_KEY, JSON.stringify(digests));
      eli.compat.lsSet(CACHE_AT_KEY, String(Date.now()));
    } catch (e) {
      // Quota — drop the cache rather than crash. Refresh just re-fetches.
      try { eli.compat.lsRemove(CACHE_KEY); eli.compat.lsRemove(CACHE_AT_KEY); } catch (_) {}
    }
  }

  // Fetch all usage digests. force=true bypasses cache.
  function _fetchAll(opts) {
    opts = opts || {};
    if (!opts.force) {
      var cached = _readCache();
      if (cached) return Promise.resolve(cached);
    }
    return auvListUsageFiles().then(function (files) {
      if (!files.length) {
        _writeCache([]);
        return { digests: [], cachedAt: Date.now() };
      }
      return Promise.all(files.map(function (f) {
        return auvFetchDigest(f.download_url);
      })).then(function (digests) {
        var clean = digests.filter(Boolean);
        _writeCache(clean);
        return { digests: clean, cachedAt: Date.now() };
      });
    }).catch(function (err) {
      eli.log.event("admin_usage_viewer", "fetch_failed", { msg: err && err.message });
      return { digests: [], cachedAt: 0 };
    });
  }

  function _downloadCsv(csvText) {
    try {
      var blob = new Blob([csvText], { type: "text/csv;charset=utf-8" });
      var url = URL.createObjectURL(blob);
      var a = document.createElement("a");
      a.href = url;
      a.download = "eli-usage-" + new Date().toISOString().slice(0, 10) + ".csv";
      document.body.appendChild(a);
      a.click();
      setTimeout(function () {
        try { document.body.removeChild(a); } catch (e) {}
        try { URL.revokeObjectURL(url); } catch (e) {}
      }, 100);
    } catch (e) {
      if (typeof showToast === "function") showToast("CSV export failed: " + (e.message || "unknown"), "err");
    }
  }

  function _paint(host, result) {
    var aggregated = auvAggregate(result.digests || []);
    renderDashboard({
      host: host,
      data: aggregated,
      totalDigests: (result.digests || []).length,
      cachedAt: result.cachedAt,
      onRefresh: function () {
        host.innerHTML = '<div class="_auv_loading">Reloading…</div>';
        _fetchAll({ force: true }).then(function (r) { _paint(host, r); });
      },
      onExport: function () {
        var csv = auvBuildCsv(result.digests || []);
        _downloadCsv(csv);
      },
    });
  }

  function _show() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedAdminUsageViewer"); } catch (e) {}
    try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") eli.fsm.transition("scanning"); } catch (e) {}
    var out = (eli.ui && typeof eli.ui.claimOutput === "function") ? eli.ui.claimOutput() : document.getElementById("output");
    if (!out) {
      if (typeof showToast === "function") showToast("Output area unavailable", "err");
      return;
    }
    out.classList.add("eli-view-enter");
    out.innerHTML = '<div class="_auv_loading">Loading usage data…</div>';
    _fetchAll({ force: false }).then(function (r) { _paint(out, r); });
  }

  eli.register({
    tile: { app_admin_usage_viewer: _show },
    admin_usage_viewer: { open: _show },
  });

  eli.log.event("tool", "admin_usage_viewer_initialized", {});
}

jsonTools.css:
/* admin_usage_viewer — admin usage dashboard.
   Class prefix `_auv_`. Light tool-panel base (per CLAUDE.md theme split). */

._auv_root {
  font-family: Inter, "Segoe UI", system-ui, sans-serif;
  color: #0f172a;
  background: #f8fafc;
  padding: 0 0 24px 0;
}

._auv_loading {
  padding: 40px 22px;
  text-align: center;
  font: 600 12px Inter, sans-serif;
  color: #475569;
}

/* ─── Header ──────────────────────────────────────────────────── */
._auv_header {
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  color: #fff;
  padding: 18px 22px;
  border-bottom: 3px solid #c9a227;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}
._auv_header_eyebrow {
  font: 800 9px/1 Inter, sans-serif;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: #c9a227;
  margin-bottom: 4px;
}
._auv_header_title {
  font: 800 22px/1.1 "Book Antiqua", Georgia, serif;
  margin: 0;
}
._auv_header_sub {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.7);
  margin-top: 4px;
}
._auv_header_btns { display: flex; gap: 8px; }

._auv_btn {
  padding: 8px 14px;
  font: 700 10px/1 Inter, sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  border: none;
  cursor: pointer;
  transition: filter 0.15s, transform 0.05s;
}
._auv_btn:active { transform: translateY(1px); }
._auv_btn_platinum {
  background: linear-gradient(180deg, #f1f5f9 0%, #cbd5e1 100%);
  color: #0f172a;
  border: 1px solid #94a3b8;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.8),
    0 1px 2px rgba(15, 23, 42, 0.08);
}
._auv_btn_platinum:hover { filter: brightness(1.04); }

/* ─── Cards ──────────────────────────────────────────────────── */
._auv_card {
  background: #fff;
  border: 1px solid #e2e8f0;
  margin: 14px 14px 0 14px;
  padding: 0;
}
._auv_card_head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  background: linear-gradient(180deg, #fcfcfd, #f8fafc);
  border-bottom: 1px solid #f1f5f9;
}
._auv_card_title {
  font: 800 11px/1 Inter, sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: #0f172a;
}
._auv_card_body { padding: 14px 16px; }
._auv_empty {
  margin: 22px 14px 0 14px;
  padding: 20px 18px;
  background: #fff;
  border: 1px dashed #cbd5e1;
  font-size: 12px;
  color: #475569;
  text-align: center;
}
._auv_empty code {
  background: #f1f5f9;
  padding: 1px 5px;
  font-family: ui-monospace, "SF Mono", Consolas, monospace;
  font-size: 11px;
}
._auv_empty_inner {
  padding: 14px 0;
  text-align: center;
  font-size: 11px;
  color: #94a3b8;
}

/* ─── Rows + bars (panels 1 & 2) ─────────────────────────────── */
._auv_list { display: flex; flex-direction: column; gap: 10px; }
._auv_row { display: flex; flex-direction: column; gap: 4px; }
._auv_row_stale { opacity: 0.55; }
._auv_row_top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
}
._auv_row_label {
  font: 700 12px Inter, sans-serif;
  color: #0f172a;
}
._auv_row_meta {
  font: 600 10px Inter, sans-serif;
  color: #64748b;
  text-align: right;
}
._auv_bar {
  height: 8px;
  background: #f1f5f9;
  border-radius: 0;
  overflow: hidden;
}
._auv_bar_fill {
  height: 100%;
  background: linear-gradient(90deg, #c9a227 0%, #e6c068 100%);
  transition: width 0.3s ease;
}

/* ─── Daily column chart (panel 3) ───────────────────────────── */
._auv_daily {
  display: flex;
  align-items: flex-end;
  gap: 6px;
  height: 140px;
  padding: 8px 0 0 0;
}
._auv_daily_col {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  min-width: 0;
}
._auv_daily_bar_wrap {
  width: 100%;
  height: 90px;
  background: #f8fafc;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}
._auv_daily_bar {
  width: 70%;
  background: linear-gradient(180deg, #e6c068 0%, #c9a227 100%);
  min-height: 2px;
  transition: height 0.3s ease;
}
._auv_daily_count {
  font: 700 11px Inter, sans-serif;
  color: #0f172a;
}
._auv_daily_date {
  font: 600 9px Inter, sans-serif;
  color: #64748b;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  white-space: nowrap;
}

/* ─── Grid (panel 4) ─────────────────────────────────────────── */
._auv_grid_head { cursor: pointer; }
._auv_grid_toggle {
  font: 700 10px Inter, sans-serif;
  color: #475569;
  letter-spacing: 0.4px;
}
._auv_grid_scroll {
  overflow-x: auto;
  border: 1px solid #f1f5f9;
}
._auv_grid_tbl {
  width: 100%;
  border-collapse: collapse;
  font-size: 11px;
}
._auv_grid_tbl thead th {
  background: #f8fafc;
  color: #475569;
  text-align: center;
  padding: 8px 6px;
  font: 700 10px Inter, sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  border-bottom: 1px solid #e2e8f0;
}
._auv_grid_tbl tbody td {
  padding: 6px;
  border-bottom: 1px solid #f1f5f9;
  text-align: center;
  vertical-align: middle;
}
._auv_grid_user_col {
  text-align: left !important;
  font: 700 11px Inter, sans-serif;
  color: #0f172a;
  padding-left: 10px !important;
  white-space: nowrap;
}
._auv_grid_cell_empty { color: #cbd5e1; }
._auv_grid_sessions {
  font: 700 12px Inter, sans-serif;
  color: #0f172a;
}
._auv_grid_toptool {
  font: 600 9px Inter, sans-serif;
  color: #94a3b8;
  margin-top: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 80px;
}

._auv_footer {
  padding: 16px 22px 0 22px;
  font-size: 10px;
  color: #94a3b8;
  text-align: center;
  line-height: 1.5;
}
._auv_footer code {
  background: #f1f5f9;
  padding: 1px 4px;
  font-family: ui-monospace, "SF Mono", Consolas, monospace;
  font-size: 10px;
}
